package com.example.starter.incident;

/**
 * 依赖图变更提案状态机：PENDING 投票中 → ACTIVATED 已原子生效 / REJECTED 已否决。
 * 任一在册人员投反对票立即进入 REJECTED；ACTIVATED 与 REJECTED 均为终态。
 */
public enum ProposalStatus {

    /** 投票中：名册成员仍可投出首次赞成或反对。 */
    PENDING,

    /** 已激活：法定人数满足后在一个事务内通过整图后态校验并原子改图。 */
    ACTIVATED,

    /** 已否决：任一名册人员投反对票，提案永久不可激活。 */
    REJECTED;
}

package com.example.starter.incident;

/**
 * 名册人员的票决：只能首次投赞成或反对，同一人员兼任多个角色席位时仍只计一票。
 */
public enum VoteChoice {

    /** 赞成：激活还要求名册中全部人员均赞成。 */
    YES,

    /** 反对：任一反对立即使提案进入 REJECTED。 */
    NO;
}

package com.example.starter.incident;

/**
 * 名册席位角色：受影响事件当时的指挥官，或提案指定的一名安全审核员。
 * 同一人员可同时承担多个席位（如既是某事件指挥官又是安全审核员）。
 */
public enum RosterRole {

    /** 受影响事件在提案创建时的现任指挥官（席位绑定具体事件）。 */
    COMMANDER,

    /** 提案创建时指定的一名安全审核员（全提案一名）。 */
    SAFETY_REVIEWER;
}

package com.example.starter.incident;

/**
 * 依赖图边的变更动作 / 边来源。
 * ADD 新增一条有向依赖边，DELETE 删除一条已有边；
 * TASK 表示边由处置任务创建引入，PROPOSAL 表示边由变更提案激活引入。
 */
public enum EdgeOp {

    /** 新增有向边（from 事件依赖 to 事件）。 */
    ADD,

    /** 删除有向边。 */
    DELETE;

    /** 任务创建引入的边。 */
    public static final String SOURCE_TASK = "TASK";

    /** 提案激活引入的边。 */
    public static final String SOURCE_PROPOSAL = "PROPOSAL";
}

