package com.example.starter.incident;

import java.time.Instant;

/**
 * 提案投票名册席位实体，对应 proposal_roster_entries 表。
 * 创建提案时冻结：每个受影响事件当时的指挥官一个 COMMANDER 席位（incidentId 绑定事件），
 * 外加一个 incidentId 为空的 SAFETY_REVIEWER 席位。
 * 名册不可变：后续指挥交接不新增、不改写已提交提案的名册。
 * 同一人员可占用多行席位（多事件指挥官或兼任审核员），投票仍按人员只计一票。
 */
public record ProposalRosterEntry(
        long id,
        long proposalId,
        Long incidentId,
        String personId,
        RosterRole role,
        Instant createdAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 提案票决实体，对应 proposal_votes 表。
 * 按人员唯一（(proposal_id, person_id)）：同一人员兼任多少席位都只投一票，
 * 该票同时代表其承担的全部角色席位；只能首次投 YES 或 NO，不可更改。
 */
public record ProposalVote(
        long id,
        long proposalId,
        String personId,
        VoteChoice choice,
        Instant votedAt,
        Instant createdAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 依赖图当前有向边实体，对应 incident_dependency_edges 表。
 * 边方向：fromIncidentId 事件的任务依赖 toIncidentId 事件（阻塞关系）。
 * source 为边来源（{@link EdgeOp#SOURCE_TASK} / {@link EdgeOp#SOURCE_PROPOSAL}），
 * refId 为来源任务或提案 id；同一条边被多个来源声明时只保留一行（结构化唯一）。
 * 提案删除边时物理删除该行；前后边集证据保存在提案快照中。
 */
public record DependencyEdge(
        long id,
        long fromIncidentId,
        long toIncidentId,
        String source,
        Long refId,
        Instant createdAt) {
}

